import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"第六章 王妃","description":"","frontmatter":{},"headers":[],"relativePath":"story/5-2.md","filePath":"story/5-2.md"}'),o={name:"story/5-2.md"};function i(n,p,s,h,l,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="第六章-王妃" tabindex="-1">第六章 王妃 <a class="header-anchor" href="#第六章-王妃" aria-label="Permalink to &quot;第六章 王妃&quot;">​</a></h1><p>王国歴十五年。</p><p>春。</p><p>王都 GOLDEN BASTION。</p><p>噴水広場。</p><p>「今日はありがとうございました。」</p><p>リリアは微笑んだ。</p><p>「こちらこそ。」</p><p>「楽しかった。」</p><p>「ふふ。」</p><p>「レックスさんって、本当に優しいですね。」</p><p>「そうかな。」</p><p>「はい。」</p><p>「すごく。」</p><p>夕焼けの中。</p><p>二人はゆっくり歩いていた。噴水の音が、二人の足音に静かに重なっていた。</p><p>そして。</p><p>リリアは小さく笑った。</p><p>「でも。」</p><p>「やっぱり。」</p><p>「王様ですよね？」</p><p>「……え？」</p><p>オーレックスは固まった。一瞬、世界の音が消えたような気がした。</p><p>「なんで！？」</p><p>「ふふふ。」</p><p>「やっぱり。」</p><p>「図星なんですね。」</p><p>「いや。」</p><p>「その。」</p><p>「えっと……。」</p><p>珍しく慌てる黄金王。エンダードラゴンの咆哮にも、皇帝の剣にも動じなかった男が、たった一言で、すっかり言葉を失っていた。</p><p>リリアは思わず吹き出した。</p><p>「そんなに慌てなくても。」</p><p>「最初から知ってました。」</p><p>「え？」</p><p>「だって。」</p><p>「王国のみんなが大好きな王様ですもの。」</p><p>「知らないわけありません。」</p><p>オーレックスは目を丸くした。</p><p>「怒らないの？」</p><p>「どうして？」</p><p>「騙してた。」</p><p>「違います。」</p><p>リリアは優しく首を振った。</p><p>「レックスさんも。」</p><p>「オーレックスさんも。」</p><p>「どっちも同じ人です。」</p><p>「私は。」</p><p>「どちらも好きですよ。」</p><p>「……。」</p><p>その瞬間。</p><p>オーレックスの心は、戦争に勝った時よりも、大きく揺れていた。剣と剣がぶつかった衝撃よりも、ずっと深いところで、何かが静かに鳴っていた。</p><p>夕焼けの色が、いつまでも、二人の間にとどまっているような気がした。</p><hr><h1 id="第七章-王宮の招待" tabindex="-1">第七章 王宮の招待 <a class="header-anchor" href="#第七章-王宮の招待" aria-label="Permalink to &quot;第七章 王宮の招待&quot;">​</a></h1><p>数日後。</p><p>「えぇぇぇぇ！？」</p><p>スターリンの叫び声が響いた。窓硝子が、わずかに震えたほどだった。</p><p>「バレてたのか！？」</p><p>「最初から。」</p><p>ピックバーグは笑いをこらえていた。</p><p>「だから言っただろう。」</p><p>「分かりやすすぎるって。」</p><p>「恥ずかしい……。」</p><p>オーレックスは机に突っ伏した。</p><p>「大丈夫だって！」</p><p>スターリンは豪快に笑う。</p><p>「むしろ最高じゃねぇか！」</p><p>「そうかな。」</p><p>「そうだ！」</p><p>「早く王宮に呼べ！」</p><p>「え？」</p><p>「いや。」</p><p>「まだ早いよ。」</p><p>「遅い！」</p><p>「お前二十五歳だぞ！」</p><p>「うっ。」</p><p>「図星。」</p><p>ピックバーグはため息をついた。</p><p>「君たち。」</p><p>「もう少し静かにできない？」</p><p>その言葉は、いつものように、誰にも届かなかった。</p><hr><p>そして。</p><p>数日後。</p><p>「すごい……。」</p><p>リリアは王宮を見上げていた。黄金の塔が、夕暮れ前の光を浴びて、淡く輝いていた。</p><p>「本当に来ちゃった。」</p><p>「緊張する？」</p><p>「少し。」</p><p>「大丈夫。」</p><p>「みんな優しいから。」</p><p>王宮の扉が開く。</p><p>「待ってたぞ！」</p><p>スターリンが飛び出してきた。勢いのまま、危うくリリアにぶつかりそうになった。</p><p>「うわっ！」</p><p>「俺はスターリン！」</p><p>「スターリンおじ……じゃなくてスターリンだ！」</p><p>「は、はい！」</p><p>「リリア・フローレンスです。」</p><p>「よろしくお願いします！」</p><p>「いい子だ！」</p><p>「気に入った！」</p><p>「まだ何も話してないよ！？」</p><p>オーレックスは慌てた。</p><p>「ふふふ。」</p><p>リリアは笑った。緊張していたはずの顔から、いつの間にか強張りが消えていた。</p><p>その後ろから、ピックバーグが現れる。</p><p>「初めまして。」</p><p>「ピックバーグです。」</p><p>「話は聞いてるよ。」</p><p>「王様をよろしく。」</p><p>「は、はい。」</p><p>「こちらこそ。」</p><p>四人は笑顔になった。長い回廊に、温かな笑い声が響いた。</p><hr><h1 id="第八章-プロポーズ" tabindex="-1">第八章 プロポーズ <a class="header-anchor" href="#第八章-プロポーズ" aria-label="Permalink to &quot;第八章 プロポーズ&quot;">​</a></h1><p>王国歴十六年。</p><p>一年が過ぎた。</p><p>春。</p><p>王宮の庭園。</p><p>初めて花をもらった場所。</p><p>あの日、無邪気な少女から一輪の花を受け取った、同じ場所だった。グロウベリーの蔓は、今日も変わらず、淡い光の粒を実らせていた。</p><p>夕日。</p><p>優しい風。</p><p>オーレックスは緊張していた。</p><p>「大丈夫。」</p><p>「戦争より簡単。」</p><p>スターリンが親指を立てる。</p><p>「全然簡単じゃない！」</p><p>「君。」</p><p>「エンダードラゴンより緊張してるね。」</p><p>ピックバーグは苦笑した。</p><p>「うぅ……。」</p><p>「怖い……。」</p><p>「頑張れ！」</p><p>「陛下！」</p><p>「行ってこい！」</p><p>二人に背中を押されるように、オーレックスは庭園の中央へ歩いていった。その背中は、初めてあの冠に手を伸ばした日の背中と、どこか似ていた。</p><hr><p>「オーレックスさん？」</p><p>庭園にやってきたリリア。</p><p>オーレックスは深呼吸した。</p><p>「リリア。」</p><p>「はい。」</p><p>「君といると。」</p><p>「毎日が楽しい。」</p><p>「うん。」</p><p>「辛い時も。」</p><p>「悲しい時も。」</p><p>「君がいてくれた。」</p><p>「……。」</p><p>「だから。」</p><p>「これから先も。」</p><p>「ずっと。」</p><p>「一緒に笑ってくれる？」</p><p>「僕と。」</p><p>「家族になってくれる？」</p><p>静寂。</p><p>風のないネザーで、それでも何かが、確かに頬を撫でた。</p><p>そして。</p><p>リリアの目から涙がこぼれた。</p><p>「……はい。」</p><p>「喜んで。」</p><p>「はい！」</p><p>夕日に照らされながら、二人は抱き合った。</p><p>その様子を遠くから見ていたスターリンは、大泣きしていた。</p><p>「うわぁぁぁん！」</p><p>「よかったなぁ！」</p><p>「静かに。」</p><p>ピックバーグも、少しだけ涙ぐんでいた。眼鏡を外し、こっそりと目元を拭った。</p><hr><h1 id="第九章-新しい物語" tabindex="-1">第九章 新しい物語 <a class="header-anchor" href="#第九章-新しい物語" aria-label="Permalink to &quot;第九章 新しい物語&quot;">​</a></h1><p>王国歴十七年。</p><p>王都 GOLDEN BASTION。</p><p>数百万の民が集まる。</p><p>王立神殿。</p><p>黄金の鐘。</p><p>花びら。</p><p>祝福。</p><p>鐘の音が、王都の隅々まで響き渡った。市場の店主も、橋を架けた村の住人も、誰もが手を止めて、その音に耳を澄ませた。</p><p>「おめでとう！」</p><p>「万歳！」</p><p>「黄金王陛下万歳！」</p><p>そして。</p><p>王立書記官が宣言した。</p><p>「ここに！」</p><p>「リリア・フローレンス！」</p><p>「王妃として迎えられることを宣言する！」</p><p>歓声。</p><p>拍手。</p><p>笑顔。</p><p>花びらが、風もないはずの空に、ゆっくりと舞い上がり、また落ちていった。まるで、王都そのものが祝福の息を吐いているようだった。</p><p>こうして。</p><p>リリア・ゴールドタスク。</p><p>PIGLIN KINGDOM初代王妃が誕生した。</p><p>そして。</p><p>黄金王と王妃の新しい物語が、静かに始まろうとしていた。</p>',198)])])}const f=a(o,[["render",i]]);export{c as __pageData,f as default};
